const report = { built: [], errors: [] };
const fail = (where, e) => report.errors.push(where + ': ' + ((e && e.message) || String(e)));
const say = (what) => report.built.push(what);

/* ── colour ─────────────────────────────────────────────────────────────── */

function hexToRgb(hex) {
  let h = String(hex || '').trim().replace('#', '');
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  if (h.length === 8) h = h.slice(0, 6);
  const n = parseInt(h, 16);
  if (Number.isNaN(n)) return { r: 0, g: 0, b: 0 };
  return {
    r: ((n >> 16) & 255) / 255,
    g: ((n >> 8) & 255) / 255,
    b: (n & 255) / 255,
  };
}
const solid = (hex, alpha) => ({
  type: 'SOLID',
  color: hexToRgb(hex),
  opacity: alpha === undefined || alpha === null ? 1 : alpha,
});

/* ── fonts ──────────────────────────────────────────────────────────────── */

const FALLBACK = { family: 'Inter', style: 'Regular' };
const loaded = new Map();

async function loadFont(family, style) {
  const key = family + '|' + style;
  if (loaded.has(key)) return loaded.get(key);
  const tries = [style, 'Regular', 'Medium', 'Bold'];
  for (const s of tries) {
    try {
      await figma.loadFontAsync({ family, style: s });
      const font = { family, style: s };
      loaded.set(key, font);
      return font;
    } catch (e) {
      /* try the next weight */
    }
  }
  try {
    await figma.loadFontAsync(FALLBACK);
  } catch (e) {
    /* Inter is bundled with the editor */
  }
  loaded.set(key, FALLBACK);
  return FALLBACK;
}

/* ── variables ──────────────────────────────────────────────────────────── */

const vars = { colour: {}, space: {}, radius: {}, motion: {} };

function makeCollection(name, modes) {
  const coll = figma.variables.createVariableCollection(name);
  const primary = coll.modes[0].modeId;
  coll.renameMode(primary, modes[0]);
  const ids = { [modes[0]]: primary };
  for (const m of modes.slice(1)) ids[m] = coll.addMode(m);
  return { coll, ids };
}

function buildVariables() {
  const colour = makeCollection('Colour', ['Light', 'Dark']);

  for (const c of DATA.colours.primitive) {
    try {
      const v = figma.variables.createVariable(c.name, colour.coll, 'COLOR');
      const paint = { ...hexToRgb(c.hex), a: c.alpha === undefined ? 1 : c.alpha };
      for (const mode of Object.keys(colour.ids)) v.setValueForMode(colour.ids[mode], paint);
      v.description = c.note || '';
      vars.colour[c.name] = v;
    } catch (e) {
      fail('variable/' + c.name, e);
    }
  }

  for (const scope of ['light', 'dark']) {
    for (const s of DATA.colours.semantic[scope] || []) {
      try {
        const existing = vars.colour[s.name];
        const v = existing || figma.variables.createVariable(s.name, colour.coll, 'COLOR');
        const modeId = colour.ids[scope === 'light' ? 'Light' : 'Dark'];
        const target = s.ref && vars.colour[s.ref];
        if (target) {
          v.setValueForMode(modeId, figma.variables.createVariableAlias(target));
        } else {
          v.setValueForMode(modeId, {
            ...hexToRgb(s.hex),
            a: s.alpha === undefined ? 1 : s.alpha,
          });
        }
        if (s.note) v.description = s.note;
        vars.colour[s.name] = v;
      } catch (e) {
        fail('variable/' + scope + '/' + s.name, e);
      }
    }
  }
  say(Object.keys(vars.colour).length + ' colour variables, 2 modes');

  const numeric = [
    ['Spacing', DATA.space, vars.space],
    ['Radius', DATA.radius, vars.radius],
    ['Motion', DATA.motion, vars.motion],
  ];
  for (const [name, list, bag] of numeric) {
    if (!list || !list.length) continue;
    try {
      const { coll, ids } = makeCollection(name, ['Default']);
      for (const t of list) {
        const v = figma.variables.createVariable(t.name, coll, 'FLOAT');
        v.setValueForMode(ids.Default, t.px);
        v.description = t.note || '';
        bag[t.name] = v;
      }
      say(list.length + ' ' + name.toLowerCase() + ' variables');
    } catch (e) {
      fail('variables/' + name, e);
    }
  }
}

/* ── styles ─────────────────────────────────────────────────────────────── */

function buildPaintStyles() {
  let n = 0;
  for (const c of DATA.colours.primitive) {
    try {
      const st = figma.createPaintStyle();
      st.name = 'Colour/' + c.name;
      const base = solid(c.hex, c.alpha);
      const v = vars.colour[c.name];
      st.paints = [v ? figma.variables.setBoundVariableForPaint(base, 'color', v) : base];
      st.description = c.note || '';
      n++;
    } catch (e) {
      fail('paint/' + c.name, e);
    }
  }
  for (const s of DATA.colours.semantic.light || []) {
    try {
      const st = figma.createPaintStyle();
      st.name = 'Colour/Semantic/' + s.name;
      const base = solid(s.hex, s.alpha);
      const v = vars.colour[s.name];
      st.paints = [v ? figma.variables.setBoundVariableForPaint(base, 'color', v) : base];
      st.description = s.note || '';
      n++;
    } catch (e) {
      fail('paint/semantic/' + s.name, e);
    }
  }
  say(n + ' paint styles');
}

async function buildTextStyles() {
  let n = 0;
  for (const t of DATA.type.roles) {
    try {
      const font = await loadFont(t.family, t.weight);
      const st = figma.createTextStyle();
      st.name = 'Type/' + t.name;
      st.fontName = font;
      st.fontSize = t.size;
      if (t.lineHeight) st.lineHeight = { unit: 'PERCENT', value: Math.round(t.lineHeight * 100) };
      if (t.tracking) st.letterSpacing = { unit: 'PIXELS', value: +(t.tracking * t.size).toFixed(2) };
      st.description = t.note || '';
      n++;
    } catch (e) {
      fail('text/' + t.name, e);
    }
  }
  say(n + ' text styles');
}

function buildEffectStyles() {
  if (!DATA.effects || !DATA.effects.length) return;
  let n = 0;
  for (const e of DATA.effects) {
    try {
      const st = figma.createEffectStyle();
      st.name = 'Elevation/' + e.name;
      st.effects = [
        {
          type: 'DROP_SHADOW',
          color: { ...hexToRgb(e.hex), a: e.alpha === undefined ? 0.18 : e.alpha },
          offset: { x: e.x || 0, y: e.y || 2 },
          radius: e.blur || 8,
          spread: e.spread || 0,
          visible: true,
          blendMode: 'NORMAL',
        },
      ];
      n++;
    } catch (err) {
      fail('effect/' + e.name, err);
    }
  }
  say(n + ' effect styles');
}

function buildGridStyles() {
  if (!DATA.grid || !DATA.grid.base) return;
  try {
    const st = figma.createGridStyle();
    st.name = 'Layout/Columns';
    st.grids = [
      {
        pattern: 'COLUMNS',
        alignment: 'STRETCH',
        count: DATA.grid.columns || 12,
        gutterSize: DATA.grid.gutter || DATA.grid.base,
        offset: 0,
        sectionSize: 0,
        visible: true,
      },
    ];
    say('1 grid style');
  } catch (e) {
    fail('grid', e);
  }
}

/* ── page furniture ─────────────────────────────────────────────────────── */

function frame(parent, name, x, y, w, h, fill) {
  const f = figma.createFrame();
  f.name = name;
  f.x = x;
  f.y = y;
  f.resize(w, h);
  f.fills = fill ? [solid(fill)] : [];
  f.clipsContent = false;
  if (parent) parent.appendChild(f);
  return f;
}

async function text(parent, content, x, y, opts) {
  const o = opts || {};
  const t = figma.createText();
  t.fontName = await loadFont(o.family || DATA.type.families.reading, o.weight || 'Regular');
  t.characters = String(content);
  t.fontSize = o.size || 16;
  t.fills = [solid(o.colour || DATA.colours.ink)];
  if (o.tracking) t.letterSpacing = { unit: 'PIXELS', value: o.tracking * (o.size || 16) };
  if (o.lineHeight) t.lineHeight = { unit: 'PERCENT', value: Math.round(o.lineHeight * 100) };
  if (o.width) {
    t.textAutoResize = 'HEIGHT';
    t.resize(o.width, t.height);
  } else {
    t.textAutoResize = 'WIDTH_AND_HEIGHT';
  }
  t.x = x;
  t.y = y;
  if (parent) parent.appendChild(t);
  return t;
}

function rect(parent, name, x, y, w, h, fill, radius) {
  const r = figma.createRectangle();
  r.name = name;
  r.x = x;
  r.y = y;
  r.resize(w, h);
  r.fills = fill ? [solid(fill)] : [];
  if (radius) r.cornerRadius = radius;
  if (parent) parent.appendChild(r);
  return r;
}

/* ── sections ───────────────────────────────────────────────────────────── */

const GUTTER = 40;

async function coverPage() {
  const page = figma.createPage();
  page.name = '00 · Cover';
  figma.currentPage = page;
  const W = 1600;
  const H = 1000;
  const f = frame(page, 'Cover', 0, 0, W, H, DATA.colours.paper);
  f.layoutMode = 'VERTICAL';
  f.primaryAxisSizingMode = 'FIXED';
  f.counterAxisSizingMode = 'FIXED';
  f.paddingTop = 96;
  f.paddingLeft = 96;
  f.paddingRight = 96;
  f.paddingBottom = 96;
  f.itemSpacing = 0;

  await text(f, DATA.name, 0, 0, {
    size: 128,
    weight: 'Bold',
    colour: DATA.colours.ink,
    tracking: -0.04,
    lineHeight: 0.92,
    family: DATA.type.families.display,
  });
  if (DATA.essence) {
    await text(f, DATA.essence, 0, 0, {
      size: 26,
      colour: DATA.colours.inkMuted || DATA.colours.ink,
      family: DATA.type.families.reading,
      width: 720,
    });
  }

  const strip = frame(f, 'palette', 0, 0, W - 192, 160, null);
  strip.layoutMode = 'HORIZONTAL';
  strip.primaryAxisSizingMode = 'FIXED';
  strip.counterAxisSizingMode = 'FIXED';
  strip.itemSpacing = 0;
  strip.paddingTop = 0;
  strip.paddingLeft = 0;
  for (const c of DATA.colours.primitive.slice(0, 8)) {
    const cell = frame(strip, c.name, 0, 0, 100, 160, c.hex);
    cell.layoutGrow = 1;
    cell.layoutAlign = 'STRETCH';
  }

  await text(f, DATA.meta || '', 0, 0, {
    size: 14,
    colour: DATA.colours.inkMuted || DATA.colours.ink,
    family: DATA.type.families.label,
    width: W - 192,
  });
  say('cover');
  return page;
}

async function colourPage() {
  const page = figma.createPage();
  page.name = '01 · Colour';
  figma.currentPage = page;
  const pad = 64;
  const cell = 200;
  const cols = 5;
  const rows = Math.ceil(DATA.colours.primitive.length / cols);
  const W = pad * 2 + cols * cell;
  const H = pad * 2 + rows * (cell + 44) + 120;
  const f = frame(page, 'Colour', 0, 0, W, H, DATA.colours.paper);

  await text(f, 'Colour', pad, pad, { size: 48, weight: 'Bold', colour: DATA.colours.ink });

  DATA.colours.primitive.forEach((c, i) => {
    const x = pad + (i % cols) * cell;
    const y = pad + 96 + Math.floor(i / cols) * (cell + 44);
    const chip = rect(f, c.name, x, y, cell - 8, cell - 8, c.hex);
    const v = vars.colour[c.name];
    if (v) chip.fills = [figma.variables.setBoundVariableForPaint(solid(c.hex), 'color', v)];
    const label = c.name + '  ' + c.hex;
    text(f, label, x, y + cell, {
      size: 13,
      colour: DATA.colours.ink,
      family: DATA.type.families.label,
    });
  });
  say('colour');
  return page;
}

async function typePage() {
  const page = figma.createPage();
  page.name = '02 · Type';
  figma.currentPage = page;
  const pad = 64;
  const W = 1280;
  let H = pad * 2 + 80;
  for (const t of DATA.type.roles) H += Math.max(64, t.size * (t.lineHeight || 1.2)) + 56;
  const f = frame(page, 'Type', 0, 0, W, H, DATA.colours.paper);
  await text(f, 'Type', pad, pad, { size: 48, weight: 'Bold', colour: DATA.colours.ink });

  let y = pad + 96;
  for (const t of DATA.type.roles) {
    await text(f, t.name + ' · ' + t.size + 'px · ' + Math.round((t.lineHeight || 1.2) * 100) + '%', pad, y, {
      size: 13,
      colour: DATA.colours.inkMuted || DATA.colours.ink,
      family: DATA.type.families.label,
    });
    const sample = DATA.samples[t.name] || DATA.name;
    await text(f, sample, pad, y + 22, {
      size: Math.min(t.size, 96),
      weight: t.weight,
      colour: DATA.colours.ink,
      family: t.family,
      tracking: t.tracking,
      lineHeight: t.lineHeight,
      width: W - pad * 2,
    });
    y += Math.max(64, t.size * (t.lineHeight || 1.2)) + 56;
  }
  say('type');
  return page;
}

async function spacePage() {
  const page = figma.createPage();
  page.name = '03 · Space & radius';
  figma.currentPage = page;
  const pad = 64;
  const W = 1200;
  const H = pad * 2 + 120 + DATA.space.length * 44 + DATA.radius.length * 90;
  const f = frame(page, 'Space and radius', 0, 0, W, H, DATA.colours.paper);
  await text(f, 'Space & radius', pad, pad, { size: 48, weight: 'Bold', colour: DATA.colours.ink });

  let y = pad + 96;
  for (const s of DATA.space) {
    rect(f, 'space/' + s.name, pad, y, Math.max(s.px, 2), 24, DATA.colours.accent);
    await text(f, s.name + ' · ' + s.px + 'px', pad + 220, y + 2, {
      size: 13,
      colour: DATA.colours.ink,
      family: DATA.type.families.label,
    });
    y += 44;
  }

  y += 24;
  let x = pad;
  for (const r of DATA.radius) {
    rect(f, 'radius/' + r.name, x, y, 96, 96, DATA.colours.raised || DATA.colours.paper, Math.min(r.px, 48));
    await text(f, r.name + ' · ' + r.px + 'px', x, y + 104, {
      size: 13,
      colour: DATA.colours.ink,
      family: DATA.type.families.label,
    });
    x += 140;
  }
  say('space + radius');
  return page;
}

async function marksPage() {
  if (!DATA.assets || !DATA.assets.length) return null;
  const page = figma.createPage();
  page.name = '04 · Marks';
  figma.currentPage = page;
  const pad = 64;
  const cell = 320;
  const cols = 3;
  const rows = Math.ceil(DATA.assets.length / cols);
  const W = pad * 2 + cols * cell;
  const H = pad * 2 + 96 + rows * (cell + 40);
  const f = frame(page, 'Marks', 0, 0, W, H, DATA.colours.paper);
  await text(f, 'Marks', pad, pad, { size: 48, weight: 'Bold', colour: DATA.colours.ink });

  for (let i = 0; i < DATA.assets.length; i++) {
    const a = DATA.assets[i];
    const x = pad + (i % cols) * cell;
    const y = pad + 96 + Math.floor(i / cols) * (cell + 40);
    const cellFrame = frame(f, a.name, x, y, cell - 16, cell - 16, DATA.colours.raised || DATA.colours.paper);
    try {
      const node = figma.createNodeFromSvg(a.svg);
      node.name = a.name;
      cellFrame.appendChild(node);
      const box = cellFrame.width - 48;
      const scale = Math.min(box / node.width, (cellFrame.height - 96) / node.height, 1);
      node.rescale(scale);
      node.x = (cellFrame.width - node.width) / 2;
      node.y = (cellFrame.height - node.height) / 2;
    } catch (e) {
      fail('mark/' + a.name, e);
    }
    await text(f, a.name, x, y + cell - 8, {
      size: 13,
      colour: DATA.colours.ink,
      family: DATA.type.families.label,
    });
  }
  say('marks: ' + DATA.assets.length);
  return page;
}

async function componentPage() {
  const page = figma.createPage();
  page.name = '05 · Components';
  figma.currentPage = page;
  const pad = 64;
  const f = frame(page, 'Components', 0, 0, 1440, 1200, DATA.colours.paper);
  await text(f, 'Components', pad, pad, { size: 48, weight: 'Bold', colour: DATA.colours.ink });

  const font = await loadFont(DATA.type.families.reading, 'Medium');
  const label = { size: 13, colour: DATA.colours.inkMuted || DATA.colours.ink, family: DATA.type.families.label };

  /* button variants */
  const intents = ['Primary', 'Secondary', 'Ghost'];
  const states = ['Default', 'Disabled'];
  const made = [];
  const host = frame(f, 'Button', pad, pad + 110, 900, 300, null);
  host.layoutMode = 'HORIZONTAL';
  host.itemSpacing = 16;
  host.paddingTop = 16;
  host.paddingLeft = 16;
  host.counterAxisSizingMode = 'AUTO';

  for (const intent of intents) {
    for (const state of states) {
      try {
        const c = figma.createComponent();
        c.name = 'Intent=' + intent + ', State=' + state;
        c.layoutMode = 'HORIZONTAL';
        c.primaryAxisSizingMode = 'AUTO';
        c.counterAxisSizingMode = 'AUTO';
        c.paddingTop = 12;
        c.paddingBottom = 12;
        c.paddingLeft = 22;
        c.paddingRight = 22;
        c.itemSpacing = 8;
        c.cornerRadius = DATA.radius.length ? DATA.radius[0].px : 0;
        const bg =
          intent === 'Primary'
            ? DATA.colours.accent
            : intent === 'Secondary'
              ? DATA.colours.raised || DATA.colours.paper
              : null;
        c.fills = bg ? [solid(bg)] : [];
        if (intent === 'Secondary') {
          c.strokes = [solid(DATA.colours.line || DATA.colours.ink)];
          c.strokeWeight = 1;
        }
        const t = figma.createText();
        t.fontName = font;
        t.characters = 'Button';
        t.fontSize = 15;
        t.fills = [solid(intent === 'Primary' ? DATA.colours.onAccent || '#ffffff' : DATA.colours.ink)];
        c.appendChild(t);
        if (state === 'Disabled') c.opacity = 0.4;
        host.appendChild(c);
        made.push(c);
      } catch (e) {
        fail('button/' + intent + '/' + state, e);
      }
    }
  }
  if (made.length) {
    try {
      const set = figma.combineAsVariants(made, host);
      set.name = 'Button';
      say('button set: ' + made.length + ' variants');
    } catch (e) {
      fail('combine/button', e);
    }
  }

  /* input states */
  const inputs = [];
  const inputHost = frame(f, 'Input', pad, pad + 470, 900, 260, null);
  inputHost.layoutMode = 'HORIZONTAL';
  inputHost.itemSpacing = 16;
  inputHost.paddingTop = 16;
  inputHost.paddingLeft = 16;
  for (const state of ['Default', 'Focus', 'Error', 'Disabled']) {
    try {
      const c = figma.createComponent();
      c.name = 'State=' + state;
      c.layoutMode = 'HORIZONTAL';
      c.primaryAxisSizingMode = 'AUTO';
      c.counterAxisSizingMode = 'AUTO';
      c.paddingTop = 12;
      c.paddingBottom = 12;
      c.paddingLeft = 14;
      c.paddingRight = 14;
      c.cornerRadius = DATA.radius.length ? DATA.radius[0].px : 0;
      c.fills = [solid(DATA.colours.raised || DATA.colours.paper)];
      c.strokes = [solid(state === 'Error' ? DATA.colours.danger || DATA.colours.accent : DATA.colours.line || DATA.colours.ink)];
      c.strokeWeight = state === 'Focus' ? 2 : 1;
      const t = figma.createText();
      t.fontName = font;
      t.characters = state === 'Default' ? 'Placeholder' : state;
      t.fontSize = 15;
      t.fills = [solid(state === 'Default' ? DATA.colours.inkMuted || DATA.colours.ink : DATA.colours.ink)];
      c.appendChild(t);
      if (state === 'Disabled') c.opacity = 0.4;
      inputHost.appendChild(c);
      inputs.push(c);
    } catch (e) {
      fail('input/' + state, e);
    }
  }
  if (inputs.length) {
    try {
      const set = figma.combineAsVariants(inputs, inputHost);
      set.name = 'Input';
      say('input set: ' + inputs.length + ' variants');
    } catch (e) {
      fail('combine/input', e);
    }
  }

  await text(f, 'Every state above is a variant, not a screenshot. Focus is a 2px ring, never a colour swap alone.', pad, pad + 780, {
    ...label,
    width: 900,
  });
  say('components');
  return page;
}

/* ── main ───────────────────────────────────────────────────────────────── */

async function main() {
  try {
    buildVariables();
  } catch (e) {
    fail('variables', e);
  }
  try {
    buildPaintStyles();
  } catch (e) {
    fail('paint styles', e);
  }
  try {
    await buildTextStyles();
  } catch (e) {
    fail('text styles', e);
  }
  try {
    buildEffectStyles();
  } catch (e) {
    fail('effect styles', e);
  }
  try {
    buildGridStyles();
  } catch (e) {
    fail('grid styles', e);
  }

  for (const builder of [coverPage, colourPage, typePage, spacePage, marksPage, componentPage]) {
    try {
      await builder();
    } catch (e) {
      fail(builder.name, e);
    }
  }

  /* Figma opens a new file on an empty "Page 1"; leaving it makes the export
   * look like a draft. Remove it only when nothing was built into it. */
  try {
    for (const page of figma.root.children) {
      if (/^Page \d+$/.test(page.name) && page.children.length === 0) page.remove()
    }
  } catch (e) {
    fail('page cleanup', e)
  }

  const summary = report.errors.length
    ? DATA.name + ': built ' + report.built.length + ', ' + report.errors.length + ' failed'
    : DATA.name + ': ' + report.built.length + ' sections built';
  figma.notify(summary, { timeout: 6000 });
  if (report.errors.length) {
    for (const e of report.errors) console.error('[forge] ' + e);
  }
  figma.closePlugin(summary);
}

main();
